Definition fout_post (U : (word * Fs.Fs) -> Prop) : post :=
  fun tr o => exists out, U out /\ tr = fout_trace out /\ exits_with (fst out) tr o.

Lemma to_fout_exec : forall ms model U,
  to_fout ms model U ->
  m_halted model = None ->
  m_vm_lazy model = [] ->
