Lemma to_fout_progress : forall ms model U,
  to_fout ms model U ->
  m_halted model = None ->
  m_vm_lazy model = [] ->
  forall evs st, sstep segs (mkCfg ms model) evs st ->
  exists ms' model', st = SNext (mkCfg ms' model') /\
    (m_halted model' <> None \/
     (m_halted model' = None /\ m_vm_lazy model' = [] /\
      exists U', to_fout ms' model' U')).
Proof.
